import {rejectionError} from './rejectionError.js';

// @spec specs/hal-engine-config-hooks/spec.md#9
it('wraps non-Error rejections with their cause and preserves existing Errors', () => {
  const original = new Error('already an Error');
  expect(rejectionError(original)).toBe(original);

  for (const rejection of ['string boom', {code: 503, detail: 'upstream down'}, undefined]) {
    const error = rejectionError(rejection);
    expect(error).toBeInstanceOf(Error);
    expect(error.message).toBe(String(rejection));
    expect(error.cause).toBe(rejection);
  }
});
EOF
timeout 300 npm test -- --runTestsByPath src/orchestration/rejectionError.test.ts --runInBand"
